import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>شعار PNG حاد لكنه ثقيل، وصورة رئيسية PNG قد تزن عدة ميغابايتات. التحويل إلى WebP يحل المشكلة دون فقدان الشفافية.</p>\n<p>العملية تستغرق ثوانٍ لكل صورة، ويمكنك تحويل مجموعة أيقونات كاملة دفعة واحدة. كل شيء يحدث على جهازك.</p>\n<p>يأخذك هذا الدليل خطوة بخطوة، مع الإعدادات التي تحمي الشفافية والنص.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: ما الذي تحتاجه؟</h2>\n<p>قبل أن تبدأ، تحتاج إلى ملفات PNG الأصلية ومعرفة وجهتها. تحقق مما إذا كانت منصتك تدعم WebP قبل التحويل.</p>\n<p>احتفظ بنسخة من الأصول PNG. الأصل هو مصدر كل نسخة مستقبلية، وقد تحتاجه إذا تغيرت المتطلبات.</p>\n<h2 id=\"step-1-open-tool\">الخطوة 1: افتح أداة PNG إلى WebP</h2>\n<p>افتح <a href=\"/ar/tahwil-png-ila-webp/\">أداة PNG إلى WebP</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"step-2-upload\">الخطوة 2: ارفع ملفات PNG</h2>\n<p>ارفع ملفات PNG: أسقطها في منطقة الرفع أو اخترها من جهازك. تُقبل ملفات PNG بأي حجم معقول.</p>\n<p>إذا رفعت عدة ملفات، فستظهر كل واحدة في قائمة. يمكنك تحويلها كلها دفعة واحدة بإعدادات موحدة.</p>\n<h2 id=\"step-3-quality\">الخطوة 3: اضبط منزلق الجودة</h2>\n<p>اضبط منزلق الجودة: جودة 90 مناسبة للشعارات والأيقونات، و85 للصور الرئيسية. جودة 95 للشعارات المهمة جدًا.</p>\n<p>للرسوم ذات النصوص، استخدم 90 أو أعلى. النص يضبب بسرعة عند الجودة المنخفضة.</p>\n<h2 id=\"step-4-convert\">الخطوة 4: حوّل الملفات</h2>\n<p>حوّل الملفات: اضغط زر التحويل وانتظر حتى تنتهي الأداة. التحويل إلى WebP سريع، والدفعة المتوسطة تستغرق دقائق معدودة.</p>\n<p>تابع شريط التقدم وانتظر حتى يكتمل التحويل. كل صورة تتحول على حدة، وتظهر النتائج تدريجيًا.</p>\n<h2 id=\"step-5-verify-transparency\">الخطوة 5: تحقق من أن الشفافية بقيت</h2>\n<p>تحقق من أن الشفافية بقيت: افتح الصورة المحوّلة على خلفية ملونة. إذا ظهرت الخلفية من خلال المناطق الشفافة، فالشفافية سليمة.</p>\n<p>إذا ظهرت الخلفية بيضاء صلبة بدل شفافة، فأعد التحويل. الشفافية المفقودة تعني إعدادًا خاطئًا أو ملفًا تالفًا.</p>\n<h2 id=\"step-6-download\">الخطوة 6: نزّل ملفات WebP</h2>\n<p>نزّل ملفات WebP: اضغط زر التنزيل واحفظ الملفات في مجلد جديد. إذا كانت عدة ملفات، فستنزّل كملف ZIP واحد.</p>\n<p>فك ضغط الملف وراجع النتائج. تحقق من أن كل ملف موجود ويبدو صحيحًا.</p>\n<ol>\n<li>ارفع ملفات PNG.</li>\n<li>اضبط الجودة.</li>\n<li>حوّل الملفات.</li>\n<li>نزّل ملفات WebP.</li>\n</ol>\n<h2 id=\"converting-an-icon-set\">تحويل مجموعة أيقونات كاملة</h2>\n<p>لتحويل مجموعة أيقونات كاملة، ارفع كل الأيقونات وحوّلها بإعدادات موحدة. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>راجع عينة من الأيقونات بعد التحويل. إذا كانت الحواف حادة والشفافية سليمة، فالدفعة ناجحة.</p>\n<h2 id=\"changing-quality-after\">تغيير الجودة بعد التحويل</h2>\n<p>لتغيير الجودة بعد التحويل، أعد التحويل من PNG الأصلي بجودة مختلفة. لا تعيد التحويل من النسخة WebP.</p>\n<p>التحويل من الأصل يحافظ على الجودة. التحويل من نسخة محوّلة يضيف فقدان جودة في كل جولة.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>لحل المشاكل الشائعة، افحص السبب أولًا. الشفافية المفقودة قد تعني إعدادًا خاطئًا، والنص الضبابي يعني جودة منخفضة.</p>\n<p>أعد التحويل من الملف الأصلي بإعدادات مختلفة. وإذا استمرت المشكلة، فتحقق من فتح الملف في عارض صور.</p>\n<h2 id=\"uploading-to-your-site\">رفع WebP إلى موقعك</h2>\n<p>لرفع WebP إلى موقعك، ارفع الملفات المحوّلة إلى منصتك كما ترفع PNG. معظم المنصات الحديثة تقبل WebP دون إضافات.</p>\n<p>تحقق من أن صفحاتك تعرض الصور بشكل صحيح بعد الرفع. إذا لم تظهر صورة، فتحقق من دعم المنصة لـWebP.</p>\n<h2 id=\"converting-logo-website\">تحويل شعار لموقع إلكتروني</h2>\n<p>لتحويل شعار لموقع إلكتروني، استخدم جودة 90. الشعار هو أول ما يراه الزائر، والجودة العالية تترك انطباعًا احترافيًا.</p>\n<p>تحقق من الشفافية بعد التحويل بفتح الشعار على خلفية ملونة. الشعار الشفاف يتكيف مع أي خلفية.</p>\n<h2 id=\"converting-icons-app\">تحويل أيقونات لتطبيق</h2>\n<p>لتحويل أيقونات لتطبيق، استخدم جودة 90 وتأكد من أن الأيقونات تبدو حادة بأحجام صغيرة. الأيقونات الصغيرة تحتاج إلى حدة عالية.</p>\n<p>تحقق من دعم نظامك لـWebP قبل التحويل. بعض أنظمة التطبيقات القديمة لا تدعم WebP.</p>\n<h2 id=\"converting-screenshots-blog\">تحويل لقطات لمدونة</h2>\n<p>لتحويل لقطات لمدونة، استخدم جودة 90. النص في اللقطات يحتاج إلى حدة عالية ليبقى مقروءًا.</p>\n<p>إذا ضبب النص بعد التحويل، فأعد التحويل بجودة أعلى. لا تحوّل من النسخة المحوّلة، بل من PNG الأصلي.</p>\n<h2 id=\"converting-product-images\">تحويل صور منتجات</h2>\n<p>لتحويل صور منتجات، استخدم جودة 90. العملاء يكبّرون الصور لفحص التفاصيل، والجودة العالية تحافظ على حدتها.</p>\n<p>حوّل كل صور المنتج بإعدادات موحدة. الاتساق يجعل المتجر يبدو احترافيًا وموثوقًا.</p>\n<h2 id=\"converting-presentation-images\">تحويل صور لعرض تقديمي</h2>\n<p>لتحويل صور لعرض تقديمي، حوّلها إلى WebP لتقليل حجم ملف العرض. العروض الكبيرة بطيئة في الفتح والمشاركة.</p>\n<p>استخدم جودة 85 لصور العروض. الجودة كافية للشاشة الكبيرة، والملف الأصغر يجعل العرض أسرع.</p>\n<h2 id=\"converting-client-brand-assets\">تحويل أصول علامة عميل</h2>\n<p>لتحويل أصول علامة عميل، استخدم إعدادات موحدة ووثّقها. أرسل ملف ZIP واحدًا مع قائمة بالمحتويات والإعدادات المستخدمة.</p>\n<p>احتفظ بالأصول PNG الأصلية. العميل قد يحتاج إلى إعادة التحويل بإعدادات مختلفة لاحقًا.</p>\n<h2 id=\"webp-for-online-courses\">WebP للدورات الإلكترونية</h2>\n<p>WebP للدورات الإلكترونية: حوّل صور الدورات إلى WebP لتسريع صفحات الدروس. الطلاب يتصفحون دروسًا كثيرة، والسرعة تحسّن تجربتهم.</p>\n<p>وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-tahwil-png-ila-webp/\">الدليل الكامل لتحويل PNG إلى WebP</a> و<a href=\"/ar/blog/png-vs-webp/\">PNG مقابل WebP</a>، أو حوّل إلى JPG باستخدام <a href=\"/ar/tahwil-png-ila-jpg/\">محول PNG إلى JPG</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أتحقق من أن الشفافية بقيت بعد التحويل؟","answer":"افتح الصورة المحوّلة على خلفية ملونة. إذا ظهرت الخلفية من خلال المناطق الشفافة، فالشفافية سليمة."},{"question":"هل يمكنني تحويل لقطات PNG إلى WebP دون تضبيب النص؟","answer":"نعم، استخدم جودة 90 أو أعلى للقطات النصية. النص يبقى حادًا وواضحًا عند الجودة العالية، ويضبب فقط عند الجودة المنخفضة."},{"question":"ما أقصى حجم ملف PNG مقبول للتحويل؟","answer":"الحد الأقصى يعتمد على متصفحك وذاكرته، لكن معظم الأدوات تقبل ملفات حتى 20 ميغابايت. الملفات الأكبر قد تحتاج إلى تقسيم."},{"question":"هل يمكنني تغيير الجودة بعد التحويل دون إعادة الرفع؟","answer":"نعم، أعد التحويل من PNG الأصلي بجودة مختلفة. لا تعيد التحويل من النسخة WebP، لأن كل جولة تضيف فقدانًا."},{"question":"هل يعمل تحويل PNG إلى WebP في متصفحات الهواتف؟","answer":"نعم، التحويل يعمل في متصفحات الهواتف الحديثة دون تثبيت أي تطبيق. افتح الأداة وارفع الصورة وحوّلها ونزّل النتيجة."},{"question":"متى أختار PNG إلى WebP بدل PNG إلى JPG؟","answer":"اختر WebP إذا احتجت إلى شفافية أو أصغر حجم للويب، وJPG إذا احتجت إلى توافق كامل مع الأنظمة القديمة."}];
